function source(start: number, text: string): SourceLine[] {
  return text
    .split("\n")
    .map((line, index) => ({ no: start + index, text: line }))
}

function library(
  prefix: string,
  file: string,
  functions: string[],
  module: string
): StackFrame[] {
  return functions.map((fn, index) => ({
    id: `${prefix}${index + 1}`,
    filename: file,
    module,
    function: fn,
    lineNo: 40 + index * 7,
    colNo: 9 + index,
    inApp: false,
  }))
}

